\title{The Collatz Map: Dynamics, a Min-Plus Stopping-Time Recurrence, and the Logic of Halting}
\author{Aristotle}
\date{2026-07-10}

\begin{document}

\begin{abstract}
The Collatz (or $3n+1$) map sends an even positive integer $n$ to $n/2$ and an odd $n$ to $3n+1$; the Collatz conjecture asserts that iterating this map from any positive integer eventually reaches $1$. We give a rigorous, self-contained development of the elementary dynamical theory of the map, isolate the precise logical shape of the conjecture and of any putative refutation, and exhibit a min-plus (tropical) recurrence governing the total stopping time. We characterize the orbits of powers of two exactly ($2^m$ reaches $1$ in precisely $m$ steps); prove that the halting predicate is invariant along the orbit and that the negation of the conjecture is the existence of a single positive counterexample; show that the halting predicate is the countable union of decidable bounded predicates, exposing the search structure of all numerical verification; and prove that the total stopping time satisfies a Bellman-type shortest-path law, $\sigma(n) = 1 + \sigma(T(n))$ for $n \neq 1$ with $\sigma(1)=0$, which is precisely the fixed-point equation of a shortest-path operator in the tropical semiring $(\N\cup\{\infty\}, \min, +)$. All results stated as theorems are unconditional; the conjecture itself is never assumed.
\end{abstract}

\maketitle

\section{Introduction}
The Collatz conjecture is among the most accessible unsolved problems in mathematics. Its statement requires nothing beyond parity and division, yet it has resisted proof since the 1930s and has been verified numerically for all starting values up to roughly $2^{68}$. The difficulty is often attributed to the competition between the contraction $n \mapsto n/2$ on even inputs and the expansion $n \mapsto 3n+1$ on odd inputs. Probabilistic heuristics suggest orbits contract on average by a factor near $3/4$ per odd step, so almost all orbits should descend to $1$; but such heuristics say nothing rigorous about every orbit, and a single divergent or non-trivially cyclic orbit would refute the conjecture.

This paper does not resolve the conjecture. Instead it (i) develops the elementary dynamics rigorously, including the exact stopping time of powers of two and the orbit-invariance of the halting predicate; (ii) pins down the logical form of the conjecture and its negation, decomposing the halting predicate into a countable union of decidable bounded predicates; and (iii) exhibits a tropical (min-plus) recurrence for the total stopping time, connecting the dynamics to shortest-path theory. Every result labeled Theorem, Proposition, or Lemma below is established unconditionally, and the conjecture is never used as a hypothesis. The much-discussed possibility of independence from strong base theories is recorded only as motivation and future work.

\section{Definitions}
Throughout, $\N = \{0,1,2,\dots\}$ and $T^{(k)}$ denotes the $k$-fold composition of $T$, with $T^{(0)}$ the identity.

\begin{definition}[Collatz map]
The \emph{Collatz map} $T : \N \to \N$ is
\[
T(n) = \begin{cases} n/2, & n \equiv 0 \pmod 2,\\ 3n+1, & n \equiv 1 \pmod 2.\end{cases}
\]
\end{definition}

\begin{definition}[Reaches]
A number $n$ \emph{reaches} $1$, written $\Reaches(n)$, if there exists $k \in \N$ with $T^{(k)}(n) = 1$.
\end{definition}

\begin{definition}[Collatz conjecture]
The \emph{Collatz conjecture} is $\Collatz :\equiv \forall n,\ (0 < n) \Rightarrow \Reaches(n)$.
\end{definition}

\begin{definition}[Bounded halting predicate]
For $b,n \in \N$, $\ReachesWithin(b,n)$ holds if there exists $k \le b$ with $T^{(k)}(n) = 1$. For each fixed $b$ this is decidable, being a finite disjunction over $k \in \{0,\dots,b\}$.
\end{definition}

\begin{definition}[Total stopping time]
If $\Reaches(n)$ holds, the \emph{total stopping time} is $\sigma(n) = \min\{k : T^{(k)}(n) = 1\}$, well defined by the least-number principle.
\end{definition}

\section{Elementary evaluation and the fixed cycle}
\begin{lemma}[Evaluation]
For all $n$: if $n$ is even then $T(n) = n/2$; if $n$ is odd then $T(n) = 3n+1$. In particular $T(2n) = n$ and $T(1) = 4$.
\end{lemma}
\begin{proof}
Immediate case analysis on $n \bmod 2$; the identity $T(2n) = 2n/2 = n$ uses exactness of division by $2$ on even inputs.
\end{proof}

\begin{lemma}[The cycle through $1$]
$T^{(3)}(1) = 1$; explicitly $1 \to 4 \to 2 \to 1$.
\end{lemma}
\begin{proof}
$T(1)=4$, $T(4)=2$, $T(2)=1$ by direct computation.
\end{proof}

\section{Orbit invariance of the halting predicate}
\begin{lemma}[Backward invariance]
If $\Reaches(T(n))$ then $\Reaches(n)$.
\end{lemma}
\begin{proof}
If $T^{(k)}(T(n)) = 1$ then $T^{(k+1)}(n) = 1$ by $T^{(k+1)}(n) = T^{(k)}(T(n))$.
\end{proof}

\begin{lemma}[Forward invariance]
If $n \neq 1$ and $\Reaches(n)$, then $\Reaches(T(n))$.
\end{lemma}
\begin{proof}
Let $k$ be least with $T^{(k)}(n) = 1$. If $k = 0$ then $n = 1$, a contradiction; hence $k = k'+1$ and $T^{(k')}(T(n)) = T^{(k'+1)}(n) = 1$.
\end{proof}

\begin{theorem}[Orbit invariance]
For $n \neq 1$, $\Reaches(n) \iff \Reaches(T(n))$.
\end{theorem}
\begin{proof}
Combine the two preceding lemmas.
\end{proof}

\section{Powers of two: exact stopping time}
\begin{theorem}[Powers of two]
For every $m \in \N$, $T^{(m)}(2^m) = 1$. Hence $\Reaches(2^m)$ and $\sigma(2^m) = m$.
\end{theorem}
\begin{proof}
Induct on $m$. For $m=0$, $T^{(0)}(1) = 1$. For the step, $2^{m+1} = 2 \cdot 2^m$, so $T(2^{m+1}) = 2^m$ and
\[
T^{(m+1)}(2^{m+1}) = T^{(m)}\big(T(2^{m+1})\big) = T^{(m)}(2^m) = 1
\]
by the inductive hypothesis. The orbit $2^m \to 2^{m-1} \to \cdots \to 1$ is strictly decreasing and does not meet $1$ before step $m$, so $\sigma(2^m) = m$.
\end{proof}

\section{Concrete orbits}
\begin{proposition}
$\Reaches(7)$ with $\sigma(7) = 16$, and $\Reaches(27)$ with $\sigma(27) = 111$.
\end{proposition}
\begin{proof}
Direct finite computation:
\[
7 \to 22 \to 11 \to 34 \to 17 \to 52 \to 26 \to 13 \to 40 \to 20 \to 10 \to 5 \to 16 \to 8 \to 4 \to 2 \to 1
\]
uses $16$ steps; the orbit of $27$ peaks at $9232$ and reaches $1$ in $111$ steps.
\end{proof}

\section{The logical shape of the conjecture}
\begin{theorem}[Refutation is a single counterexample]
\[
\lnot\,\Collatz \iff \exists n,\ (0 < n) \land \lnot\,\Reaches(n).
\]
\end{theorem}
\begin{proof}
$\Collatz$ is $\forall n,\ 0 < n \Rightarrow \Reaches(n)$; its negation is $\exists n,\ 0 < n \land \lnot\Reaches(n)$ by the prenex laws.
\end{proof}

\begin{theorem}[Search decomposition]
For all $n$, $\Reaches(n) \iff \exists b,\ \ReachesWithin(b,n)$.
\end{theorem}
\begin{proof}
If $T^{(k)}(n)=1$ then $\ReachesWithin(k,n)$ with witness $k \le k$. Conversely $\ReachesWithin(b,n)$ gives some $k \le b$ with $T^{(k)}(n)=1$, so $\Reaches(n)$.
\end{proof}

Since each $\ReachesWithin(b,\cdot)$ is decidable, $\Reaches$ is a countable union of decidable bounded predicates, i.e.\ a $\Sigma_1$ predicate, with \emph{no uniform bound} on $b$ as a function of $n$. The growth of the least such $b$ (equivalently of $\sigma(n)$) is the sole quantity a finite proof must control.

\section{The min-plus stopping-time recurrence}
\begin{theorem}[Bellman / min-plus recurrence]
$\sigma(1) = 0$, and for every $n \neq 1$ that reaches $1$,
\[
\sigma(n) = 1 + \sigma\big(T(n)\big).
\]
\end{theorem}
\begin{proof}
$\sigma(1)=0$ since $T^{(0)}(1)=1$. For $n \neq 1$, forward invariance gives that $T(n)$ reaches $1$. Now $T^{(\sigma(T(n))+1)}(n) = T^{(\sigma(T(n)))}(T(n)) = 1$, so $\sigma(T(n))+1$ is a witness. For minimality, if $j < \sigma(T(n))+1$ with $T^{(j)}(n)=1$ then $j = i+1$ with $i < \sigma(T(n))$ and $T^{(i)}(T(n)) = 1$, contradicting minimality of $\sigma(T(n))$. Hence $\sigma(n) = \sigma(T(n)) + 1$.
\end{proof}

\paragraph{Tropical interpretation.} In the min-plus semiring $\mathbb{T} = (\N \cup \{\infty\}, \oplus, \otimes)$ with $a \oplus b = \min(a,b)$ and $a \otimes b = a+b$, model the positive integers as a directed graph with a single edge $n \to T(n)$ of weight $1$ and sink $1$ with $\sigma(1)=0$. The general Bellman equation $\sigma(n) = \bigoplus_{m: n \to m}(w(n,m) \otimes \sigma(m))$ collapses, since $T$ has the unique successor $T(n)$ of weight $1$, to $\sigma(n) = 1 \otimes \sigma(T(n)) = 1 + \sigma(T(n))$. Thus the total stopping time is the shortest-path length to the sink, and $\sigma$ is a fixed point of the tropical Bellman operator $\Phi$ with $(\Phi f)(1)=0$, $(\Phi f)(n) = 1 + f(T(n))$. The Collatz conjecture is exactly the assertion that $\Phi$ admits a total (everywhere-finite) least fixed point on the positive integers.

\section{Algorithms}
\textbf{Algorithm A (Orbit / stopping time).} Iterate $T$ from $n$, counting steps until $1$; computes $\sigma(n)$ and terminates iff $\Reaches(n)$, with no a priori step bound.

\textbf{Algorithm B (Bounded verifier).} Iterate $T$ at most $b$ times; decides $\ReachesWithin(b,n)$ and always terminates. Range verification runs this for each $n \le N$.

\textbf{Algorithm C (Tropical fixed-point sweep).} On a finite $T$-closed window, initialize $\sigma(1)=0$, $\sigma(n)=\infty$ otherwise, and repeatedly apply $\sigma(n) \leftarrow \min(\sigma(n), 1 + \sigma(T(n)))$ until stable; Bellman--Ford specialized to the single-successor graph.

\section{Discussion and future work}
It is often speculated that the conjecture is independent of strong base theories. We assert no such result; we establish only the structural setting: $\Collatz$ is $\Pi_2$, its refutation is a single $\Sigma_1$ witness, and its positive content is a countable union of decidable facts with no uniform bound. Future directions include (i) proving $\sigma$ is the least fixed point of $\Phi$ and that $\Phi$ contracts in a natural graph metric; (ii) analyzing the growth of the certificate bound $b(N) = \max_{n \le N}\sigma(n)$; (iii) reducing the halting problems for $T$ and the odd-step map $n \mapsto (3n+1)/2$ by stopping-time-preserving translations; and (iv) developing tropical obstructions to nontrivial cycles.

\section{Conclusion}
From a one-sentence rule we extracted the exact stopping time of powers of two, orbit-invariance of halting, the single-witness form of refutation, the decomposition of halting into decidable bounded searches, and a tropical Bellman recurrence identifying the stopping time as a shortest-path function. These results locate the conjecture's difficulty in the uncontrolled growth of a certificate bound and connect the problem to tropical dynamics and the logic of provability. The conjecture remains open; its structure is now sharply drawn.

\end{document}

