from typing import List, Optional

def collatz(n: int) -> int:
    """Collatz map T: n/2 if even, else 3n+1."""
    return n // 2 if n % 2 == 0 else 3 * n + 1

def orbit(n: int, max_steps: int = 100000) -> List[int]:
    """Full orbit [n, T(n), ...] up to the first 1."""
    seq = [n]
    while seq[-1] != 1 and len(seq) <= max_steps:
        seq.append(collatz(seq[-1]))
    return seq

def stopping_time(n: int) -> Optional[int]:
    """Least k with T^k(n) = 1."""
    o = orbit(n)
    return (len(o) - 1) if o[-1] == 1 else None

if __name__ == "__main__":
    for n in (6, 7, 27, 97):
        o = orbit(n)
        print(f"n={n:3d}  sigma={stopping_time(n):3d}  peak={max(o):5d}")

