def collatz(n: int) -> int:
    return n // 2 if n % 2 == 0 else 3 * n + 1

def stopping_time(n: int) -> Optional[int]:
    x, k = n, 0
    while x != 1:
        x = collatz(x); k += 1
        if k > 10**6: return None
    return k

if __name__ == "__main__":
    # Theorem: sigma(2^m) = m exactly. Powers of two are the geodesics.
    for m in range(0, 16):
        assert stopping_time(2**m) == m
        print(f"2^{m:<2d} = {2**m:<6d}  sigma = {m}")
    print("Verified sigma(2^m) = m for m = 0..15.")

from typing import Dict

def collatz(n: int) -> int:
    return n // 2 if n % 2 == 0 else 3 * n + 1

def stopping_time_memo(n: int, memo: Dict[int, int]) -> int:
    """Compute sigma via the min-plus recurrence sigma(n) = 1 + sigma(T(n))."""
    stack = []
    x = n
    while x not in memo:
        stack.append(x)
        x = collatz(x)
    base = memo[x]
    while stack:
        y = stack.pop()
        base += 1
        memo[y] = base
    return memo[n]

if __name__ == "__main__":
    memo = {1: 0}
    for n in range(2, 21):
        s = stopping_time_memo(n, memo)
        # check the Bellman recurrence directly
        assert s == 1 + memo[collatz(n)]
        print(f"sigma({n:2d}) = {s:3d} = 1 + sigma(T({n})) = 1 + {memo[collatz(n)]}")

