from typing import List, Optional

def collatz(n: int) -> int:
    return n // 2 if n % 2 == 0 else 3 * n + 1

def orbit_and_stopping_time(n: int, max_steps: int = 10**7) -> Optional[List[int]]:
    """Return the orbit [n,...,1], or None if 1 is not reached within max_steps.

    Complexity: O(sigma(n)) map applications; sigma(n) has no known bound in n."""
    seq: List[int] = [n]
    while seq[-1] != 1:
        if len(seq) > max_steps:
            return None
        seq.append(collatz(seq[-1]))
    return seq

def reaches_within(b: int, n: int) -> bool:
    """Decide ReachesWithin(b, n): does the orbit of n hit 1 within b steps?

    Always terminates in at most b+1 map applications. Decidable for every fixed b."""
    x = n
    for _ in range(b + 1):
        if x == 1:
            return True
        x = x // 2 if x % 2 == 0 else 3 * x + 1
    return False

from typing import Dict

def collatz(n: int) -> int:
    return n // 2 if n % 2 == 0 else 3 * n + 1

def tropical_stopping_times(window: int) -> Dict[int, float]:
    """Min-plus Bellman-Ford sweep computing sigma on {1,...,window}.

    Relaxation:  sigma(n) <- min(sigma(n), 1 + sigma(T(n))),  sigma(1)=0.
    Complexity:  O(V * E) worst case = O(V^2) on the single-successor graph,
    where V is the number of nodes reachable from the window."""
    inf = float("inf")
    nodes = set()
    for start in range(1, window + 1):
        x = start
        while x not in nodes:
            nodes.add(x)
            if x == 1:
                break
            x = collatz(x)
    sigma: Dict[int, float] = {v: (0.0 if v == 1 else inf) for v in nodes}
    changed = True
    while changed:
        changed = False
        for v in nodes:
            if v == 1:
                continue
            cand = 1 + sigma[collatz(v)]
            if cand < sigma[v]:
                sigma[v] = cand
                changed = True
    return {v: sigma[v] for v in range(1, window + 1)}
